def parse_nested_parens(paren_string: str) -> List[int]:
    groups = paren_string.split()
    levels = []
    for group in groups:
        count = 0
        max_count = 0
        for char in group:
            if char == '(':
                count += 1
                if count > max_count:
                    max_count = count
            elif char == ')':
                count -= 1
        levels.append(max_count)
    return levels

